import { describe, expect, it } from 'vitest';
import { formatLspFile } from '@styleTokens/emitters/generate/format/formatLspFile';
function createTokenGroup(overrides = {}) {
    return {
        name: 'button',
        styleName: 'buttonStyle',
        typeName: 'ButtonStyle',
        tokenFile: '/generated/tokenModules/button.token.ts',
        tokens: [
            {
                infix: 'button',
                variables: [
                    {
                        key: 'color',
                        cssName: 'color',
                        allowed: ['p', 'f'],
                        values: {
                            p: '#ff0000',
                            f: '#000000',
                        },
                    },
                ],
            },
        ],
        ...overrides,
    };
}
function createLspData(overrides = {}) {
    return {
        rgbVariables: [],
        ...overrides,
    };
}
describe('[EMITTER]', () => {
    describe('formatLspFile', () => {
        it('returns the generated metadata file path', () => {
            const result = formatLspFile([], createLspData());
            expect(result.filePath).toContain('/src/shared/generated/metadata/cssVariables.generated.ts');
        });
        it('emits the generated file header', () => {
            const result = formatLspFile([], createLspData());
            expect(result.content).toContain('// AUTO-GENERATED FILE.');
            expect(result.content).toContain('// DO NOT EDIT.');
            expect(result.content).toContain('// Generated by design-tokens-plugin.');
        });
        it('emits a token variable with its allowed value chain', () => {
            const [group] = [
                createTokenGroup(),
            ];
            const result = formatLspFile([group], createLspData());
            expect(result.content).toContain('//button {');
            expect(result.content).toContain('//--final-button-color: 🔮 color: p:#ff0000 → f:#000000;');
        });
        it('emits defined prefix variables with their values', () => {
            const result = formatLspFile([createTokenGroup()], createLspData());
            expect(result.content).toContain('//--p-button-color: #ff0000;');
            expect(result.content).toContain('//--f-button-color: #000000;');
        });
        it('emits prefixes without values in the chain', () => {
            const result = formatLspFile([
                createTokenGroup({
                    tokens: [
                        {
                            infix: 'button',
                            variables: [
                                {
                                    key: 'color',
                                    cssName: 'color',
                                    allowed: ['p', 'f'],
                                    values: {
                                        p: '#ff0000',
                                    },
                                },
                            ],
                        },
                    ],
                }),
            ], createLspData());
            expect(result.content).toContain('//--final-button-color: 🔮 color: p:#ff0000 → f;');
            expect(result.content).not.toContain('///--f-button-color:');
        });
        it('uses the group name when the token infix matches it', () => {
            const result = formatLspFile([
                createTokenGroup({
                    name: 'button',
                    tokens: [
                        {
                            infix: 'button',
                            variables: [],
                        },
                    ],
                }),
            ], createLspData());
            expect(result.content).toContain('//button {');
        });
        it('includes the token infix in the block name when it differs from the group name', () => {
            const result = formatLspFile([
                createTokenGroup({
                    name: 'button',
                    tokens: [
                        {
                            infix: 'hover',
                            variables: [],
                        },
                    ],
                }),
            ], createLspData());
            expect(result.content).toContain('//button-hover {');
        });
        it('emits multiple token variables', () => {
            const result = formatLspFile([
                createTokenGroup({
                    tokens: [
                        {
                            infix: 'button',
                            variables: [
                                {
                                    key: 'background',
                                    cssName: 'background',
                                    allowed: ['p'],
                                    values: {
                                        p: '#fff',
                                    },
                                },
                                {
                                    key: 'color',
                                    cssName: 'color',
                                    allowed: ['f'],
                                    values: {
                                        f: '#000',
                                    },
                                },
                            ],
                        },
                    ],
                }),
            ], createLspData());
            expect(result.content).toContain('//--final-button-background: 🔮 background: p:#fff;');
            expect(result.content).toContain('//--final-button-color: 🔮 color: f:#000;');
        });
        it('emits LSP RGB variables in the root block', () => {
            const result = formatLspFile([], createLspData({
                rgbVariables: [
                    '--button-color: rgb(100% 0% 0%)',
                    '--button-background: rgb(0% 0% 0%)',
                ],
            }));
            expect(result.content).toContain('//:root {');
            expect(result.content).toContain('//--button-color: rgb(100% 0% 0%);');
            expect(result.content).toContain('//--button-background: rgb(0% 0% 0%);');
        });
        it('emits empty token and root collections', () => {
            const result = formatLspFile([], createLspData());
            expect(result.content).toContain('//:root {');
        });
    });
});
